-- The terrain generator dbcraft:noise (sql/855) and the dbcraft.generator setting.
-- There is no vanilla oracle for this terrain (it is NOT vanilla's), so what is checked is what can be: the setting and the flat path stay as they were, the chunks are a
-- pure function of (seed, coordinates), neighbouring chunks agree on their borders, the heightmaps written with a chunk equal a full recompute from its blocks, counts and
-- block content are consistent, the wire encoding of the generated sections decodes (by an independent decoder) to the stored blocks, the generation queue produces them,
-- and the biome containers and the surface layering are what sql/855 says.
\! python3 tools/load_world_ref.py

------------------------------------------------------------------------------------------------ the setting and the flat default
select t.eq('the default generator is flat', mc.prop('dbcraft.generator'), 'minecraft:flat');
select t.eq('...and the overworld uses it', (select generator from mc.dimension where name = 'minecraft:overworld'), 'minecraft:flat');
-- flat generation through the dispatching path is the reference's, byte for byte (the template path of sql/245 against mc.generate_flat_slow)
insert into mc.dimension (name) values ('dbcraft:flatref');
insert into mc.flat_layer (dimension, y, block) select 'dbcraft:flatref', y, block from mc.flat_layer where dimension = 'minecraft:overworld';
select mc.generate_flat_slow('dbcraft:flatref', 7, 9, true);
select mc.generate_flat('minecraft:overworld', 7, 9, true);
create function pg_temp.flatdig(p_dim text, p_cx int, p_cz int) returns text language sql stable as $$
  select md5(string_agg(sy || ':' || block_count || ':' || fluid_count || ':' || palette::text || ':' || bits || ':' || md5(data) || ':' || biome_palette::text || ':' || biome_bits || ':' || md5(biome_data), '|' order by sy))
    from mc.chunk_section where dimension = p_dim and cx = p_cx and cz = p_cz $$;
select t.eq('a flat chunk generated by mc.generate_flat equals the reference generator''s (sections)', pg_temp.flatdig('minecraft:overworld', 7, 9), pg_temp.flatdig('dbcraft:flatref', 7, 9));
select t.eq('...and so does its packet (bytes after the coordinates)', substring(mc.chunk_packet('minecraft:overworld', 7, 9) from 14), substring(mc.chunk_packet('dbcraft:flatref', 7, 9) from 14));
select t.raises('an unknown generator is refused', $q$update mc.server_property set value = 'minecraft:nope' where key = 'dbcraft.generator'$q$);
select t.eq('...and nothing changed', (select generator from mc.dimension where name = 'minecraft:overworld'), 'minecraft:flat');

update mc.world set seed = 424242 where name = 'world';
update mc.server_property set value = 'dbcraft:noise' where key = 'dbcraft.generator';
select t.eq('the setting moves the overworld to the noise generator', (select generator from mc.dimension where name = 'minecraft:overworld'), 'dbcraft:noise');
select t.is_true('...and the spawn onto dry land (the generator''s height at the spawn is 66 or more, the player stands one above)',
                 (select mc.terrain_height(424242, spawn_x, spawn_z) >= 66 and spawn_y = mc.terrain_height(424242, spawn_x, spawn_z) + 1 from mc.dimension where name = 'minecraft:overworld'));
select t.is_true('...in mc.game_state too (what the join sends)', (select (gs.spawn_x, gs.spawn_y, gs.spawn_z) = (d.spawn_x + 0.5, d.spawn_y::float8, d.spawn_z + 0.5) from mc.game_state gs, mc.dimension d where d.name = 'minecraft:overworld'));
select mc.generate_flat('minecraft:overworld', 20, 20, true);
select t.is_true('mc.generate_flat in a noise dimension makes a noise chunk (at least 8 stored sections, the flat chunk has 1)',
                 (select count(*) >= 8 from mc.chunk_section where dimension = 'minecraft:overworld' and cx = 20 and cz = 20));
select t.eq('...with its packet cached and its light computed',
            (select (not c.dirty, k.version = c.version)::text from mc.chunk c join mc.chunk_cache k on k.dimension = c.dimension and k.cx = c.cx and k.cz = c.cz where c.dimension = 'minecraft:overworld' and c.cx = 20 and c.cz = 20), '(t,t)');
update mc.server_property set value = 'minecraft:flat' where key = 'dbcraft.generator';
select t.eq('switching back restores the flat generator and the flat spawn', (select (generator, spawn_x, spawn_y, spawn_z)::text from mc.dimension where name = 'minecraft:overworld'), '(minecraft:flat,0,-60,0)');
select mc.generate_flat('minecraft:overworld', 7, 9, true);
select t.eq('...and flat chunks are the reference''s again', pg_temp.flatdig('minecraft:overworld', 7, 9), pg_temp.flatdig('dbcraft:flatref', 7, 9));

------------------------------------------------------------------------------------------------ a region of terrain
insert into mc.dimension (name, generator) values ('dbcraft:n1', 'dbcraft:noise'), ('dbcraft:n2', 'dbcraft:noise');
select clock_timestamp() as t0 \gset
select mc.generate_noise_batch('dbcraft:n1', array_agg(x), array_agg(z)) as made from generate_series(-6, 5) x, generate_series(-6, 5) z \gset
select (extract(epoch from clock_timestamp() - :'t0'::timestamptz) * 1000 / 144)::numeric(8, 2) as ms_per_chunk \gset
select t.eq('a 12 x 12 region: 144 chunks created', :made, 144);
\echo INFO terrain generation, light and packet: :ms_per_chunk ms per chunk (144 chunks in one call)
select t.eq('...a second call creates none', mc.generate_noise_batch('dbcraft:n1', array[0, 1], array[0, 1]), 0);
select t.eq('...every chunk has its packet cached and clean', (select count(*)::int from mc.chunk c join mc.chunk_cache k on k.dimension = c.dimension and k.cx = c.cx and k.cz = c.cz and k.version = c.version
                                                                where c.dimension = 'dbcraft:n1' and not c.dirty and not c.hm_dirty), 144);

-- determinism: the same seed gives the same chunks, byte for byte; another seed does not
create function pg_temp.terrdig(p_dim text) returns text language sql stable as $$
  select md5(string_agg(c.cx || ',' || c.cz || ':' || c.hm_world_surface::text || ':' || coalesce(s.d, ''), '|' order by c.cx, c.cz))
    from mc.chunk c, lateral (select string_agg(sy || ':' || block_count || ':' || fluid_count || ':' || palette::text || ':' || bits || ':' || md5(data) || ':' || biome_palette::text || ':' || biome_bits || ':' || md5(biome_data), ';' order by sy) d
                                from mc.chunk_section s where s.dimension = c.dimension and s.cx = c.cx and s.cz = c.cz) s
   where c.dimension = p_dim $$;
select pg_temp.terrdig('dbcraft:n1') as dig1 \gset
select mc.generate_noise_batch('dbcraft:n2', array_agg(x), array_agg(z)) from generate_series(-6, 5) x, generate_series(-6, 5) z;
select t.eq('the same seed in another dimension makes the same terrain', pg_temp.terrdig('dbcraft:n2'), :'dig1');
select mc.generate_noise_batch('dbcraft:n2', array_agg(x), array_agg(z), true) from generate_series(-6, 5) x, generate_series(-6, 5) z;
select t.eq('...and so does generating it again over itself (replace)', pg_temp.terrdig('dbcraft:n2'), :'dig1');
update mc.world set seed = 424243 where name = 'world';
select mc.generate_noise_batch('dbcraft:n2', array_agg(x), array_agg(z), true) from generate_series(-6, 5) x, generate_series(-6, 5) z;
select t.is_true('a different seed makes different terrain', pg_temp.terrdig('dbcraft:n2') <> :'dig1');
update mc.world set seed = 424242 where name = 'world';
select mc.generate_noise_batch('dbcraft:n2', array_agg(x), array_agg(z), true) from generate_series(-6, 5) x, generate_series(-6, 5) z;
select t.eq('...and going back to the first seed gives the first terrain again', pg_temp.terrdig('dbcraft:n2'), :'dig1');
-- the chunks do not depend on which batch they were generated in (neighbours, order): one chunk alone equals the same chunk from the region
select mc.generate_noise_batch('dbcraft:n2', array[3], array[-2], true);
select t.eq('one chunk generated alone equals the chunk of the region', (select hm_world_surface::text from mc.chunk where dimension = 'dbcraft:n2' and cx = 3 and cz = -2), (select hm_world_surface::text from mc.chunk where dimension = 'dbcraft:n1' and cx = 3 and cz = -2));

------------------------------------------------------------------------------------------------ heights: the function against the stored heightmaps, continuity
select t.eq('the stored WORLD_SURFACE of 600 columns equals the surface height function (higher of the surface and the sea) + 65',
            (select count(*)::int from (select c.cx, c.cz, i, c.hm_world_surface[i + 1] as h from mc.chunk c, generate_series(0, 255, 7) i where c.dimension = 'dbcraft:n1' and (c.cx + c.cz + i) % 4 = 0 limit 600) q
              where q.h <> greatest(mc.terrain_height(424242, q.cx * 16 + (q.i % 16), q.cz * 16 + (q.i / 16)), 62) + 65), 0);
select t.is_true('...over a range of more than 40 blocks of height in the region', (select max(h) - min(h) > 40 from (select unnest(hm_world_surface) h from mc.chunk where dimension = 'dbcraft:n1') q));
-- no jump between neighbouring columns, inside a chunk or across a chunk border (a 4-block lattice with smoothstep: slopes stay small)
create temp table cols as select c.cx * 16 + (i % 16) as x, c.cz * 16 + (i / 16) as z, c.hm_world_surface[i + 1] as h from mc.chunk c, generate_series(0, 255) i where c.dimension = 'dbcraft:n1';
create index on cols (x, z);
select max(abs(a.h - b.h)) as max_slope from cols a join cols b on (b.x = a.x + 1 and b.z = a.z) or (b.x = a.x and b.z = a.z + 1) \gset
select t.is_true('neighbouring columns differ by at most 6 blocks (the formula allows about 3 per block; measured maximum: ' || :max_slope || ')', :max_slope <= 6);
select t.is_true('...including across chunk borders (the largest step on a border is no larger than the largest inside)',
  (select coalesce(max(abs(a.h - b.h)), 0) from cols a join cols b on (b.x = a.x + 1 and b.z = a.z and a.x % 16 = 15) or (b.x = a.x and b.z = a.z + 1 and a.z % 16 = 15))
  <= (select max(abs(a.h - b.h)) from cols a join cols b on (b.x = a.x + 1 and b.z = a.z and a.x % 16 <> 15) or (b.x = a.x and b.z = a.z + 1 and a.z % 16 <> 15)));

------------------------------------------------------------------------------------------------ heightmaps and light
select t.eq('the heightmaps written with the chunks equal a full recompute from the blocks (36 chunks, all three kinds)',
            (select count(*)::int from mc.chunk c cross join lateral mc.compute_heightmaps(c.dimension, c.cx, c.cz) h
              where c.dimension = 'dbcraft:n1' and c.cx between -3 and 2 and c.cz between -3 and 2
                and (c.hm_world_surface, c.hm_motion_blocking, c.hm_motion_blocking_no_leaves) is distinct from (h.world_surface, h.motion_blocking, h.motion_blocking_no_leaves)), 0);
select t.is_true('...and water raised the heightmaps of columns below the sea (62 + 65 = 127) while land columns kept theirs',
                 (select count(*) filter (where h = 127) > 0 and count(*) filter (where h > 127) > 0 from (select unnest(hm_world_surface) h from mc.chunk where dimension = 'dbcraft:n1') q));
select t.eq('light rows exist for the chunks (mc.ensure_chunk_current ran when the generator built the packets)',
            (select count(*)::int from mc.chunk c where c.dimension = 'dbcraft:n1' and c.cx between -3 and 2 and c.cz between -1 and 0 and not exists (select 1 from mc.chunk_light l where l.dimension = c.dimension and l.cx = c.cx and l.cz = c.cz)), 0);

------------------------------------------------------------------------------------------------ blocks
-- layering of columns: bedrock at the bottom, deepslate below y 0, stone, a surface profile, water to y 62
create temp table samp as
  select c.cx, c.cz, i % 16 as lx, i / 16 as lz, c.hm_world_surface[i + 1] - 65 as top
    from mc.chunk c, generate_series(0, 255, 17) i where c.dimension = 'dbcraft:n1' and c.cx between -3 and 2 and c.cz between -3 and 2;
select t.eq('y = -64 is bedrock in every sampled column (' || count(*) || ' columns)', count(*) filter (where mc.get_block('dbcraft:n1', cx * 16 + lx, -64, cz * 16 + lz) <> 'minecraft:bedrock')::int, 0) from samp;
select t.eq('y = -59 and below y 0 is deepslate, y = -1 too', count(*) filter (where mc.get_block('dbcraft:n1', cx * 16 + lx, -59, cz * 16 + lz) <> 'minecraft:deepslate[axis=y]'
                                                                          or mc.get_block('dbcraft:n1', cx * 16 + lx, -1, cz * 16 + lz) <> 'minecraft:deepslate[axis=y]')::int, 0) from samp;
select t.is_true('bedrock fills 1 to 5 layers per column (all five values occur)', (select count(distinct n) = 5 from
   (select (select count(*) from generate_series(-64, -60) y where mc.get_block('dbcraft:n1', cx * 16 + lx, y, cz * 16 + lz) = 'minecraft:bedrock') n from samp) q));
select t.eq('y = 0 is stone wherever the surface is 9 or more blocks above', count(*) filter (where top >= 9 and mc.get_block('dbcraft:n1', cx * 16 + lx, 0, cz * 16 + lz) <> 'minecraft:stone')::int, 0) from samp;
create function pg_temp.check_column(p_cx int, p_cz int, p_lx int, p_lz int, p_top int) returns text language plpgsql as $f$
declare x int := p_cx * 16 + p_lx; z int := p_cz * 16 + p_lz; b text := mc.get_block('dbcraft:n1', x, p_top, z); y int;
begin
    if b = 'minecraft:water[level=0]' then                                  -- a wet column: water up to y 62 exactly, a sand or gravel floor under it, air above
        if p_top <> 62 then return 'water top at ' || p_top; end if;
        y := p_top;
        while mc.get_block('dbcraft:n1', x, y, z) = 'minecraft:water[level=0]' loop y := y - 1; end loop;
        if mc.get_block('dbcraft:n1', x, y, z) not in ('minecraft:sand', 'minecraft:gravel') then return 'floor ' || mc.get_block('dbcraft:n1', x, y, z); end if;
        if mc.get_block('dbcraft:n1', x, 63, z) <> 'minecraft:air' then return 'no air above the water'; end if;
        return null;
    end if;
    if b not in ('minecraft:grass_block[snowy=false]', 'minecraft:sand', 'minecraft:stone', 'minecraft:snow_block', 'minecraft:gravel') then return 'top block ' || b; end if;
    if mc.get_block('dbcraft:n1', x, p_top + 1, z) <> 'minecraft:air' then return 'no air above the top block'; end if;
    return null;
end $f$;
select t.eq('every sampled column is layered right: a dry column ends in grass, sand, gravel, stone or snow with air above; a wet one in water at y 62 over a sand or gravel floor',
            count(*) filter (where pg_temp.check_column(cx, cz, lx, lz, top) is not null)::int, 0) from samp;
select t.is_true('the region has dry land with at least 2 kinds of surface block',
                 (select count(*) filter (where top >= 63) > 0 from samp)
             and (select count(distinct mc.get_block('dbcraft:n1', cx * 16 + lx, top, cz * 16 + lz)) >= 2 from samp where top >= 63));
select t.is_true('seen over 4,225 points 200 blocks apart (the height function): sea (below 62) is 20 to 60 percent, land of 66 or more 20 to 70 percent, hills above 100 exist',
                 (select count(*) filter (where h < 62) between 845 and 2535 and count(*) filter (where h >= 66) between 845 and 2957 and count(*) filter (where h > 100) > 0
                    from (select mc.terrain_height(424242, x * 200, z * 200) h from generate_series(-32, 32) x, generate_series(-32, 32) z) q));
-- counts: block_count and fluid_count of every section equal what the blocks say (a sample of sections, 4,096 blocks each)
select t.eq('block_count and fluid_count of 30 sections equal a count of their blocks',
            (select count(*)::int from (select s.* from mc.chunk_section s where s.dimension = 'dbcraft:n1' and s.cx between -1 and 0 and s.cz between -1 and 0 and s.sy between 0 and 8) s,
                   lateral (select count(*) filter (where block <> 'minecraft:air') as nonair, count(*) filter (where mc.has_fluid(block)) as fl from mc.section_blocks(s, true)) b
              where b.nonair <> s.block_count or b.fl <> s.fluid_count), 0);

------------------------------------------------------------------------------------------------ the wire encoding of the generated sections
create function pg_temp.decode_blocks(w bytea) returns int[] language plpgsql as $f$
declare o int := 4; bits int; n int; pal int[] := '{}'; r record; vpl int; len int; vals int[]; i int;
begin
    bits := get_byte(w, o); o := o + 1;
    if bits = 0 then select * into r from proto.varint_read(w, o); return array_fill(r.val, array[4096]); end if;
    if bits <= 8 then
        select * into r from proto.varint_read(w, o); n := r.val; o := r.nxt;
        for i in 1 .. n loop select * into r from proto.varint_read(w, o); pal := pal || r.val; o := r.nxt; end loop;
    end if;
    vpl := 64 / bits; len := ((4096 + vpl - 1) / vpl) * 8;
    vals := mc.unpack_longs(substring(w from o + 1 for len), bits, 4096);
    if bits <= 8 then vals := array(select pal[e + 1] from unnest(vals) with ordinality t(e, k) order by k); end if;
    return vals;
end $f$;
select t.eq('wire decode of section ' || s.sy || ' of chunk (' || s.cx || ',' || s.cz || ') (' || s.bits || ' bits) matches the stored blocks', d.ids is not distinct from w.want, true)
from mc.chunk_section s,
     lateral (select pg_temp.decode_blocks(mc.section_wire(s)) as ids) d,
     lateral (select array(select mc.state_id(b.block) from mc.section_blocks(s, true) b order by (b.y - s.sy * 16) * 256 + (b.z - s.cz * 16) * 16 + (b.x - s.cx * 16)) as want) w
where s.dimension = 'dbcraft:n1' and s.cx = 0 and s.cz = 0 and s.sy in (-4, -1, 0, 4, 5, 6);
select t.eq('the packet of a generated chunk starts with its coordinates and is a full chunk packet (more than 10 KB of section bytes)',
            (select (substring(p from o.o2 + 1 for 8) = int4send(3) || int4send(-2) and length(p) > 10000)::text
               from (select mc.chunk_packet('dbcraft:n1', 3, -2) p) q, lateral (select (proto.varint_read(q.p, (proto.varint_read(q.p, 0)).nxt)).nxt as o2) o), 'true');

------------------------------------------------------------------------------------------------ biomes
select t.is_true('the region uses at least 5 different biomes, all real registry entries',
                 (select count(distinct b) >= 5 from (select unnest(biome_palette) b from mc.chunk_section where dimension = 'dbcraft:n1') q)
             and not exists (select 1 from (select unnest(biome_palette) b from mc.chunk_section where dimension = 'dbcraft:n1') q where not exists (select 1 from mc.biome m where m.name = q.b)));
select t.is_true('...with palette containers of 1, 2 and 3 bits and single-value ones', (select count(distinct biome_bits) >= 3 from mc.chunk_section where dimension = 'dbcraft:n1'));
select t.eq('every biome container has the byte length of its width (64 entries, floor(64 / bits) per long)',
            (select count(*)::int from mc.chunk_section where dimension = 'dbcraft:n1' and octet_length(biome_data) <> case biome_bits when 0 then 0 else ((64 + (64 / biome_bits) - 1) / (64 / biome_bits)) * 8 end), 0);
-- the biome of every 4 x 4 cell, decoded from the stored container (written here, not by the generator) against the biome the noise functions give at the cell's lattice point
create function pg_temp.cell_biomes(p_cx int, p_cz int) returns text[] language plpgsql as $f$
declare s mc.chunk_section; per int; e int; w bigint; res text[] := '{}'; pidx int;
begin
    select * into s from mc.chunk_section where dimension = 'dbcraft:n1' and cx = p_cx and cz = p_cz and sy = -3;
    for e in 0 .. 15 loop                                               -- the cells of the lowest layer: index (z << 2 | x)
        if s.biome_bits = 0 then pidx := 0;
        else
            per := 64 / s.biome_bits;
            w := proto.i64_read(s.biome_data, (e / per) * 8);
            pidx := ((w >> ((e % per) * s.biome_bits)) & ((1::bigint << s.biome_bits) - 1))::int;
        end if;
        res := res || s.biome_palette[pidx + 1];
    end loop;
    return res;
end $f$;
create function pg_temp.expected_biomes(p_cx int, p_cz int) returns text[] language sql stable as $f$
  select array_agg((mc.terrain_biomes())[mc.t_biome(floor(smp.h)::int, smp.temp, smp.hum)] order by cj, ci)
    from generate_series(0, 3) cj, generate_series(0, 3) ci, lateral mc.t_sample(424242, p_cx * 16 + 4 * ci, p_cz * 16 + 4 * cj) smp $f$;
select t.eq('the stored biome container of 40 chunks decodes to the biome the noise gives in each of the 16 cells (640 cells)',
            (select count(*)::int from (select cx, cz from mc.chunk where dimension = 'dbcraft:n1' and (cx * 7 + cz * 3) % 3 = 0 limit 40) q where pg_temp.cell_biomes(cx, cz) is distinct from pg_temp.expected_biomes(cx, cz)), 0);
-- the cell grid is the same in every section of a chunk and constant in height: the first and the last stored section of a chunk carry the same container
select t.eq('a chunk''s sections share one biome container', (select count(*)::int from (select cx, cz, count(distinct (biome_palette::text, biome_bits, biome_data)) n from mc.chunk_section where dimension = 'dbcraft:n1' group by cx, cz) q where n <> 1), 0);

------------------------------------------------------------------------------------------------ the generation queue
select mc.pregenerate('dbcraft:n2', 40, 40, 2, false) as queued \gset
select t.is_true('chunks of a noise dimension are queued like any other (' || :queued || ' requests)', :queued > 0);
select t.eq('...the generator loop turns them into chunks with their packets', mc.generate_pending(100), 25);
select t.eq('...each cached and clean', (select count(*)::int from mc.chunk c join mc.chunk_cache k on k.dimension = c.dimension and k.cx = c.cx and k.cz = c.cz and k.version = c.version
                                          where c.dimension = 'dbcraft:n2' and c.cx between 38 and 42 and c.cz between 38 and 42 and not c.dirty), 25);
select t.raises('a dimension of another shape is refused', $q$insert into mc.dimension (name, min_y, height, generator) values ('dbcraft:short', 0, 256, 'dbcraft:noise'); select mc.generate_noise_batch('dbcraft:short', array[0], array[0])$q$);
select t.raises('an unknown dimension is refused', $q$select mc.generate_noise_batch('dbcraft:nowhere', array[0], array[0])$q$);
